var vals = Enumerable.Range(0, 1000).Select(_ => Random.Shared.Next(0, 50)).ToArray();
var c = Solution.CountUnique(vals);
var expected = vals.Distinct().Count();
Cj.Eq(c, expected, "concurrent counting is exact, not approximate");

var d = new ConcurrentDictionary<string, int>();
int computed = 0;
Cj.True(Solution.TryAddIfAbsent(d, "k", s => Interlocked.Increment(ref computed)), "first add wins");
Cj.False(Solution.TryAddIfAbsent(d, "k", s => Interlocked.Increment(ref computed)), "repeat returns false");
Cj.Eq(computed, 1, "factory never re-runs once the key exists");
Cj.Eq(d["k"], 1, "value present");
